import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(__dirname, '..');
const iconsFile = path.join(projectRoot, 'src/lib/weather/icons.ts');
const outputDir = path.join(projectRoot, 'src/lib/weather/bundled');

// Ensure output directory exists
if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
}

// Read icons.ts to find used icons
const iconsContent = fs.readFileSync(iconsFile, 'utf8');

// Regex to find icon names: 'prefix:name'
const iconRegex = /'([a-z0-9-]+):([a-z0-9-]+)'/g;
const usedIcons = {
    'wi': new Set(),
    'meteocons': new Set(),
    'material-symbols-light': new Set()
};

let match;
while ((match = iconRegex.exec(iconsContent)) !== null) {
    const [full, prefix, name] = match;
    if (usedIcons[prefix]) {
        usedIcons[prefix].add(name);
    }
}

console.log('Found icons:', {
    wi: usedIcons.wi.size,
    meteocons: usedIcons.meteocons.size,
    material: usedIcons['material-symbols-light'].size
});

function bundleIcons(packageName, prefix, iconsSet) {
    const iconSetPath = path.join(projectRoot, 'node_modules', '@iconify-json', packageName, 'icons.json');

    if (!fs.existsSync(iconSetPath)) {
        console.error(`Error: Package ${packageName} not found at ${iconSetPath}`);
        return;
    }

    const iconSetData = JSON.parse(fs.readFileSync(iconSetPath, 'utf8'));
    const bundledData = {
        prefix: prefix,
        icons: {},
        aliases: {}, // Add aliases if needed
        width: iconSetData.width,
        height: iconSetData.height
    };

    const missing = [];

    iconsSet.forEach(iconName => {
        if (iconSetData.icons[iconName]) {
            bundledData.icons[iconName] = iconSetData.icons[iconName];
        } else if (iconSetData.aliases && iconSetData.aliases[iconName]) {
            // Resolve simple alias
            const alias = iconSetData.aliases[iconName];
            bundledData.aliases[iconName] = alias;
            // We might need to include the target of the alias too if it's not already included
            if (alias.parent && !bundledData.icons[alias.parent] && iconSetData.icons[alias.parent]) {
                bundledData.icons[alias.parent] = iconSetData.icons[alias.parent];
            }
        } else {
            missing.push(iconName);
        }
    });

    if (missing.length > 0) {
        console.warn(`Warning: Missing icons in ${packageName}:`, missing);
    }

    const outputPath = path.join(outputDir, `${prefix}.ts`);
    const fileContent = `// Auto-generated by scripts/bundle-icons.js
export default ${JSON.stringify(bundledData, null, 2)};
`;

    fs.writeFileSync(outputPath, fileContent);
    console.log(`Bundled ${packageName} to ${outputPath} (${Object.keys(bundledData.icons).length} icons)`);
}

// Bundle each set
bundleIcons('wi', 'wi', usedIcons.wi);
bundleIcons('meteocons', 'meteocons', usedIcons.meteocons);
bundleIcons('material-symbols-light', 'material-symbols-light', usedIcons['material-symbols-light']);

// Create index file
const indexContent = `// Auto-generated register file
import "iconify-icon";
// @ts-ignore
import wi from './wi';
// @ts-ignore
import meteocons from './meteocons';
// @ts-ignore
import material from './material-symbols-light';

export function registerWeatherIcons() {
  const iconify = customElements.get('iconify-icon');
  if (iconify && 'addCollection' in iconify) {
      // @ts-ignore
      iconify.addCollection(wi);
      // @ts-ignore
      iconify.addCollection(meteocons);
      // @ts-ignore
      iconify.addCollection(material);
      console.log('Weather icons registered');
  }
}
`;

fs.writeFileSync(path.join(outputDir, 'index.ts'), indexContent);
console.log('Created index.ts');
